/* U.S. Military Peace & Civilian Protection OS — public-interest prototype (2026-10-14)
 * Sections:
 * 1. Canonical routes, source registries, topic data
 * 2. Accessible UI shell and reports
 * 3. IndexedDB/local records; validated portable public-only records
 * 4. SHA-256/provenance; manual reciprocal handoffs
 * 5. Accessible events, controls and service-worker state
 * Integrity: SHA-256 proves byte equality, not authorship; no telemetry or agency access.
 */
(()=>{'use strict';
const ROOT=document.querySelector('meta[name="app-root"]')?.content||'./';
const PAGE=document.body.dataset.route||'home';
const APP='us_military_peace_research_os',DB='us_military_peace_research_db',VERSION=1,DATE='2026-10-14';
const ROUTES=[{"id":"home","path":"","title":"Overview","hint":"Mission dashboard and policy boundaries","group":"Foundation","sym":"◈"},{"id":"sitrep","path":"modules/sitrep/","title":"SITREP · 2026-10-14","hint":"Dated facts, uncertainty and civilian risk","group":"Assess","sym":"◎"},{"id":"doctrine","path":"modules/doctrine/","title":"Mission & legal scope","hint":"DoD authorities, U.S. and international law","group":"Assess","sym":"§"},{"id":"casebook","path":"modules/casebook/","title":"Public evidence casebook","hint":"Documented sources and alternative readings","group":"Assess","sym":"▤"},{"id":"register","path":"modules/register/","title":"Local research ledger","hint":"Public-source notes stored on device","group":"Assess","sym":"▦"},{"id":"evidence","path":"modules/evidence/","title":"Evidence & provenance","hint":"Chain of claims and SHA-256 integrity","group":"Verify","sym":"◇"},{"id":"compliance","path":"modules/compliance/","title":"Sustainment assurance","hint":"Lawful acquisition and end-use oversight","group":"Verify","sym":"⬡"},{"id":"framework","path":"modules/framework/","title":"Intervention register","hint":"Phased nonviolent support actions","group":"Plan","sym":"⌁"},{"id":"cyber","path":"modules/cyber/","title":"Defensive cyber","hint":"Resilience and integrity without intrusion","group":"Plan","sym":"⛨"},{"id":"humanitarian","path":"modules/humanitarian/","title":"Civilian protection","hint":"Humanitarian access, POWs, reconstruction","group":"Plan","sym":"✳"},{"id":"ceasefire","path":"modules/ceasefire/","title":"Ceasefire verification","hint":"Incident rules and reciprocal incentives","group":"Plan","sym":"◉"},{"id":"metrics","path":"modules/metrics/","title":"Metrics & monitoring","hint":"Outcomes, indicators and data caveats","group":"Evaluate","sym":"▥"},{"id":"premortem","path":"modules/premortem/","title":"24-month premortem","hint":"Spoilers, failure pathways and mitigations","group":"Evaluate","sym":"△"},{"id":"nodes","path":"modules/nodes/","title":"Reciprocal nodes","hint":"Public-only drafts for USSS/FBI/CIA/UN","group":"Coordinate","sym":"⟡"},{"id":"governance","path":"modules/governance/","title":"Governance & backups","hint":"Privacy, correction, portability and sources","group":"Coordinate","sym":"▣"}];
const SOURCES=[{"id":"UN-OCT","date":"2026-10-08","type":"UN primary","title":"OHCHR: Civilian attacks, energy disruption and all-party IHL protections","url":"https://ukraine.un.org/en/324088-comment-un-human-rights-chief-volker-t%C3%BCrk-deadly-strikes-ukraine"},{"id":"UN-AUG","date":"2026-09-17","type":"UN verified data","title":"OHCHR: Protection of civilians in August 2026","url":"https://ukraine.un.org/en/323454-protection-civilians-armed-conflict-%E2%80%94-august-2026"},{"id":"UN-SEP","date":"2026-09-24","type":"UN diplomacy","title":"UN General Assembly discussions of civilian protection and peace","url":"https://ukraine.un.org/en/323265-un-general-assembly-calls-protection-civilians-and-just-peace-ukraine"},{"id":"UN-ENERGY","date":"2026-06-29","type":"UN primary","title":"OHCHR: Systematic attacks against Ukraine energy infrastructure","url":"https://ukraine.un.org/en/318327-attacks-against-ukraine%E2%80%99s-energy-infrastructure-and-update-human-rights-situation-ukraine-1"},{"id":"UN-COM","date":"2026-09-21","type":"UN commission","title":"UN Commission: Energy infrastructure and civilian conditions","url":"https://ukraine.un.org/en/323052-un-commission-concerned-about-human-impact-russia%E2%80%99s-systematic-targeting-energy"},{"id":"DOD-CHMR","date":"2022-08-25","type":"US official policy","title":"DoD Civilian Harm Mitigation and Response Action Plan","url":"https://www.defense.gov/News/Releases/Release/Article/3140007/civilian-harm-mitigation-and-response-action-plan-fact-sheet/"},{"id":"DOD-CHMR-I","date":"2023-12-21","type":"US official policy","title":"DoD Instruction 3000.17 explained","url":"https://www.defense.gov/News/News-Stories/Article/Article/3624268/dod-issues-civilian-harm-mitigation-response-instruction/"},{"id":"DOD-CHMR-REG","date":"accessed 2026-10-14","type":"US official documents","title":"DoD Policy civilian harm mitigation and annual reports","url":"https://policy.defense.gov/Offices/Civilian-Harm-Mitigation-and-Response/"},{"id":"BIS-CHPL","date":"accessed 2026-10-14","type":"Export law guidance","title":"BIS Common High Priority Items List","url":"https://media.bis.gov/licensing/country-guidance/common-high-priority-items-list-chpl"},{"id":"STATE-EUM","date":"archived 2025","type":"US official guidance","title":"State Department Blue Lantern end-use monitoring","url":"https://2021-2025.state.gov/end-use-monitoring-of-u-s-origin-defense-articles/"},{"id":"UN-CHARTER","date":"1945","type":"Primary law","title":"Charter of the United Nations","url":"https://www.un.org/en/about-us/un-charter/full-text"},{"id":"ICRC-IHL","date":"accessed 2026-10-14","type":"Humanitarian law","title":"ICRC overview of international humanitarian law","url":"https://www.icrc.org/en/law-and-policy/international-humanitarian-law"},{"id":"CISA","date":"accessed 2026-10-14","type":"US official cyber","title":"CISA Report a Cyber Issue","url":"https://www.cisa.gov/report"},{"id":"DOD-LAW","date":"accessed 2026-10-14","type":"US official law","title":"DoD Law of War Manual resources","url":"https://ogc.osd.mil/Law-of-War/"},{"id":"DOJ-GOLTSEV","date":"2025-01-08","type":"Judicial outcome","title":"DOJ: Goltsev export-control conspiracy sentencing","url":"https://www.justice.gov/usao-edny/pr/canadian-national-sentenced-40-months-prison-multi-million-dollar-export-control"},{"id":"DOJ-SHEV","date":"2026-07-23","type":"Guilty plea","title":"DOJ: Andrey Shevlyakov procurement conspiracy guilty plea","url":"https://www.justice.gov/usao-edny/pr/estonian-national-pleads-guilty-exporting-electronics-benefit-russian-military"}];
const CASES=[{"name":"UN: August 2026 civilian casualties","date":"2026-09-17","classification":"UN VERIFIED RECORD","disposition":"At least 372 killed and 2,349 injured in August 2026 per OHCHR snapshot","source":"UN-AUG","fact":"OHCHR documented civilian harm across Ukraine and warned that published figures represent verified minimums.","limits":"Monthly totals can be revised; do not compare incompatible report vintages or infer a live count."},{"name":"UN: October civilian-protection concern","date":"2026-10-08","classification":"UN OFFICIAL REPORT","disposition":"UN human rights chief condemned deadly attacks and highlighted outages and risks to civilians.","source":"UN-OCT","fact":"Documented public concern for civilians throughout Ukraine, including deaths from Russian strikes and allegations of civilian harm in Russian-controlled areas or Russia.","limits":"Some incident numbers are attributed to local authorities pending independent verification."},{"name":"DoD: civilian-harm policy","date":"2023-12-21","classification":"POLICY DOCUMENT","disposition":"DoDI 3000.17 framework for civilian-harm mitigation and response.","source":"DOD-CHMR-I","fact":"U.S. DoD described institutional requirements to mitigate and assess civilian harm during U.S. military operations.","limits":"Does not grant this application official DoD authority or apply to all foreign military actions unchanged."},{"name":"DOJ: unlawful electronics procurement case","date":"2026-07-23","classification":"GUILTY PLEA","disposition":"Andrey Shevlyakov pleaded guilty to export violations.","source":"DOJ-SHEV","fact":"Specific illicit supply-chain case illustrates why distributor knowledge, manufacturer origin and criminal law must be separated.","limits":"A conviction for a scheme is not proof every branded component maker knowingly supported illicit transfers."}];
const CHECKS=[{"id":"mandate","title":"Jurisdiction and mandate identified","description":"Confirm legal owner, civilian oversight and no assumed DoD domestic police function."},{"id":"law","title":"International and domestic law reviewed","description":"UN Charter, IHL, human rights, procurement laws and applicable sanctions."},{"id":"consent","title":"Host-nation and humanitarian consent respected","description":"Confirm consent and do not treat neutral humanitarian organizations as intelligence sources."},{"id":"sources","title":"Evidence class and date recorded","description":"Separate verified fact, official claim, legal finding, inference, and unknown."},{"id":"harm","title":"Civilian-harm second-order effects assessed","description":"Review disruption of water, food, electricity, medical services and displacement."},{"id":"ceasefire","title":"Verification and adjudication independent","description":"Define evidence, violations, accidents, observers and adjudicators with consent."},{"id":"sanctions","title":"Supply-chain and sanctions proportionality reviewed","description":"Protect lawful self-defense, humanitarian exceptions and innocent manufacturers."},{"id":"cyber","title":"Defensive cyber only","description":"No access to networks, covert monitoring or intrusion; no unit positions or operational indicators."},{"id":"security","title":"No protected data exposed","description":"Exclude classified data, restricted plans, active operations, intelligence sources and personal identifiers."},{"id":"fallback","title":"Stop rule and fallback set","description":"Define a reversible contingency if facts fail, consent ends or civilian harm rises."}];
const ACTIONS=[{"time":"0–72 hours","owner":"Civilian-harm research team / voluntary NGO partners","ask":"Publish a dated, sourced civilian-impact brief and correct evident data errors.","mechanism":"Shared factual baseline for diplomacy and humanitarian prioritization.","gate":"Public-source only; protect survivor privacy and verification standards.","measure":"Cited corrections and independently confirmed protection gaps.","stop":"Remove claims when primary evidence fails; do not publish sensitive locations.","cost":"Low for desk research; uncertain staffing."},{"time":"0–72 hours","owner":"DoD public liaison / legal-policy staff, subject to authorization","ask":"Audit existing public civilian-harm procedures and create an accountable referral map.","mechanism":"Direct problems to proper government or humanitarian mechanisms.","gate":"DoD policy approval; do not pretend official intake.","measure":"Mandates documented and channels verified.","stop":"Stop if a proposed referral compromises neutrality or exposes personal data.","cost":"Low to moderate administrative."},{"time":"2–6 weeks","owner":"U.S. departments and licensed contractors","ask":"Review existing end-use and supplier integrity controls for authorized defense assistance.","mechanism":"Discourage unlawful diversion without obstructing legitimate defense.","gate":"Acquisition counsel, legal scope, exporter protections.","measure":"Documented audit completion and verified discrepancies resolved.","stop":"Suspend speculative referrals; preserve due process.","cost":"Moderate, organization-dependent."},{"time":"2–6 weeks","owner":"Civil defense / authorized infrastructure partners","ask":"Coordinate non-sensitive energy, water and medical restoration gaps with Ukrainian consent.","mechanism":"Reduce harm and the pressure created by infrastructure attacks.","gate":"Host consent, humanitarian independence and deconfliction requirements.","measure":"Restored service days, verified civilian access, outage duration.","stop":"Pause when shared data could reveal critical vulnerabilities.","cost":"Variable; potentially substantial materials."},{"time":"2–6 months","owner":"Diplomats with UN/OSCE consultation; states must consent","ask":"Design a pilot reciprocal energy and civilian-infrastructure non-attack arrangement.","mechanism":"A bounded, measurable confidence-building step.","gate":"Explicit parties’ acceptance; no implied military enforcement mandate.","measure":"Independent incident reviews and service interruptions.","stop":"No unilateral sanctions relief before verified response.","cost":"Moderate monitoring, high diplomatic coordination."},{"time":"2–6 months","owner":"Independent monitoring body authorized by parties","ask":"Establish protected incident-intake and adjudication rules for a limited truce.","mechanism":"Separate deliberate violations, misidentification, accidents and disputed allegations.","gate":"Access, mandate, security, confidentiality, data standards.","measure":"Time to acknowledge and adjudicate incidents; reversals and corrections.","stop":"Withhold disputed findings pending verification.","cost":"Staffing and infrastructure dependent."},{"time":"6–24 months","owner":"Governments / authorized guarantors / humanitarian stakeholders","ask":"Develop monitored general ceasefire with security safeguards and reciprocal conditionality.","mechanism":"Make renewed aggression less attractive and breaches observable.","gate":"Mutual consent, legal review, ceasefire scope and enforcement accountability.","measure":"Verified compliance, humanitarian access, POW and missing-person progress.","stop":"Escalate violations through agreed lawful dispute process; preserve civilian access.","cost":"High, negotiation-dependent."},{"time":"2–10 years","owner":"Ukraine, affected communities, donor governments, auditors","ask":"Support civilian-led repair, demining, accountable reconstruction and non-recurrence institutions.","mechanism":"Lower long-run instability, empower return and support durable security.","gate":"Sovereignty, public procurement audit, affected-population voice.","measure":"Safe return, verified cleared land, school/water uptime, grievance remedy.","stop":"Halt projects with unresolved displacement, corruption or environmental harm.","cost":"Very high, multiyear and context-specific."}];
const NODES=[{"id":"usss","name":"U.S. Secret Service","status":"prior research edition","scope":"Financial crime and protective remit; not military command."},{"id":"fbi","name":"FBI","status":"prior research edition","scope":"Federal investigation and domestic national-security laws; no presumption of case transfer."},{"id":"cia","name":"CIA","status":"future edition","scope":"Foreign intelligence under lawful oversight; not a domestic police function."},{"id":"dod","name":"U.S. Military / DoD","status":"this independent concept","scope":"Defense policy, civilian harm mitigation, assistance governance and lawful support."},{"id":"bis","name":"Commerce BIS / OEE","status":"concept referral only","scope":"Export controls and specialized compliance; not DoD military investigation."},{"id":"state","name":"U.S. Department of State","status":"concept referral only","scope":"Diplomacy, security assistance/end-use oversight and legal foreign-policy channels."},{"id":"un","name":"United Nations","status":"future concept","scope":"Civilian protection and diplomacy under multilateral mandate."},{"id":"icrc","name":"ICRC","status":"independent external","scope":"Neutral humanitarian mandate; never used as an intelligence handoff."}];
const st={db:null,storage:'loading',records:[],events:[],checks:{},pending:null,editing:null,search:'',filter:'all',theme:'light',sw:'not installed',hash:null,hashname:'',hud:false};
const $=(s,el=document)=>el.querySelector(s), $$=(s,el=document)=>Array.from(el.querySelectorAll(s));
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function url(x){try{const u=new URL(x);return u.protocol==='https:'&&!u.username&&!u.password&&u.href.length<=700?u.href:null;}catch{return null;}}
const link=(u,label)=>url(u)?`<a href="${esc(url(u))}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`:esc(label);
const source=id=>SOURCES.find(x=>x.id===id);
const cite=id=>source(id)?link(source(id).url,'Source: '+id):esc(id);
const path=id=>ROOT+(ROUTES.find(x=>x.id===id)||ROUTES[0]).path+'index.html';
function localGet(k,f=''){try{return localStorage.getItem(APP+'_'+k)??f;}catch{return f;}}
function localSet(k,v){try{localStorage.setItem(APP+'_'+k,v);return true;}catch{return false;}}
function toast(msg){let x=$('#toast');if(!x)return;x.textContent=msg;x.classList.remove('hidden');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>x.classList.add('hidden'),5500);}
function newId(){return crypto?.randomUUID?.()||('r'+Date.now().toString(36)+Math.random().toString(36).slice(2));}
function hero(title,desc,category='RESEARCH SYSTEM',tags=[]){return `<section class="banner"><div class="eyebrow">${esc(category)} · DOD-FOCUSED PUBLIC CONCEPT · EDITION 03</div><h1>${esc(title)}</h1><p>${esc(desc)}</p><div class="tagrow">${['PUBLIC-SOURCE ONLY','OFFLINE CORE','NO AGENCY ACCESS',...tags].map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="banner-meta">Fact freeze ${DATE} · Public-interest prototype · Not affiliated with any agency</div></section>`;}
function card(title,body,kicker=''){return `<article class="card searchable">${kicker?`<span class="kicker">${esc(kicker)}</span>`:''}<h3>${esc(title)}</h3>${body}</article>`;}
function sourcesHTML(){return `<ul class="source-list">${SOURCES.map(s=>`<li class="searchable"><span class="sourceid">${esc(s.id)}</span> · ${link(s.url,s.title)}<small>${esc(s.date)} · ${esc(s.type)}</small></li>`).join('')}</ul>`;}
function readiness(){const done=CHECKS.filter(x=>st.checks[x.id]).length;return `<div class="card"><div class="coverline"><h3>Review checklist progress</h3><strong>${done}/${CHECKS.length}</strong></div><div class="progress" role="progressbar" aria-label="Governance checklist completion" aria-valuemin="0" aria-valuemax="${CHECKS.length}" aria-valuenow="${done}"><div style="width:${done/CHECKS.length*100}%"></div></div><p class="small muted">Reflects steps marked as reviewed on this device, never proof of investigative readiness.</p></div>`;}
function home(){return hero('Military-supported peace: civilian protection, verification and lawful cooperation','A civilian-facing, unofficial systems workspace for evidence-based de-escalation, accountable assistance and lasting protection. Not a command-and-control system.','MISSION OVERVIEW',['15 MODULES'])+`
<section class="metrics"><div class="metric"><div class="value">15</div><div class="label">Interlinked HTML pages</div><div class="meta">Independent offline reading</div></div><div class="metric"><div class="value">${st.records.length}</div><div class="label">Local public-source notes</div><div class="meta">No cloud sync</div></div><div class="metric"><div class="value">0</div><div class="label">Agency connections</div><div class="meta">Unsigned drafts only</div></div><div class="metric"><div class="value">${SOURCES.length}</div><div class="label">Source references</div><div class="meta">Links available online</div></div></section>
<section class="section"><h2>Separation of functions</h2><div class="columns">${card('Military responsibilities, not military targeting',`<p>Public doctrine review, civilian harm mitigation, assistance accountability, logistics assurance, and possible consent-based ceasefire verification. No troop movements, target selection or strike design.</p>${cite('DOD-CHMR-I')}`,'MISSION')}${card('Diplomacy and enforcement remain institutionally distinct',`<p>State leads foreign diplomacy; DOJ/BIS/HSI/FBI have distinct investigative or regulatory roles; the UN and ICRC maintain separate mandates. This site issues no official requests or orders.</p>${cite('UN-SEP')}`,'BOUNDARIES')}</div></section>
<section class="section"><h2>Module constellation</h2><div class="nodegrid">${ROUTES.filter(r=>r.id!=='home').map(r=>card(r.title,`<p class="small">${esc(r.hint)}.</p><a class="card-cta" href="${path(r.id)}">Open module →</a>`,r.group)).join('')}</div></section>
<section class="section"><h2>Evidence-to-action pathway</h2><div class="diagram"><div><b>Observe</b>Public facts</div><div><b>Verify</b>Independent corroboration</div><div><b>Scope</b>Legal mandate</div><div><b>Protect</b>Civilian consequences</div><div><b>Review</b>Consent & correction</div></div><div class="callout warn"><b>Hard stop:</b> Do not enter restricted plans, classified data, military dispositions, coordinates of vulnerable assets, personal dossiers or nonpublic operational intelligence. Never use this tool for lethal targeting or offensive cyber.</div></section>
<section class="section"><h2>Governance status</h2>${readiness()}<div class="local-warning">The interface stores public research notes only when your browser permits it. Browser storage is not encrypted. Export safely and verify before sharing.</div></section>`;}
function sitrep(){return hero('SITREP | Russia–Ukraine: October 14, 2026','A dated, public-source fact freeze; current reality may change after publication. The application makes no live operational claims.','SITUATION REPORT',['PUBLIC DATA ONLY'])+`
<section class="section"><h2>Executive assessment</h2><div class="callout"><b>Verified:</b> The UN human rights office reported at least 372 civilians killed and 2,349 injured in Ukraine during August 2026, with long-range weapon strikes a leading cause. On October 8, the UN condemned recent deadly strikes and warned about winter energy disruptions. <br>${cite('UN-AUG')} · ${cite('UN-OCT')}</div><div class="columns">${card('Verified civilian exposure',`<p>Systematic attacks on energy infrastructure have affected essential services. Civilian protection and rights of populations in occupied territory remain urgent. ${cite('UN-ENERGY')}</p>`,'UN FACT')}${card('Political settlement conditions','<p>The UN has called for a just peace respecting Ukraine’s sovereignty. Proposals for a ceasefire are not equivalent to a monitored, accepted agreement, and a ceasefire alone is not proof of durable peace.</p>'+cite('UN-SEP'),'VERIFIED POSITION')}${card('Industrial and procurement support',`<p>Dual-use items found in Russian weapons raise export compliance questions. Product origin alone is not proof of an illicit export or manufacturer knowledge. ${cite('BIS-CHPL')}</p>`,'LEGAL DISTINCTION')}${card('This system cannot observe the battlefield','<p>No real-time ISR, intelligence feeds, protected databases, command authorization or classified reporting exists. Threat or compliance status shown here must not be interpreted as live.</p>','UNKNOWN / BOUNDARY')}</div></section>
<section class="section"><h2>Evidence and contradictions ledger</h2><div class="table-wrap"><table><thead><tr><th>Finding / date</th><th>Confidence</th><th>Operational implication (non-tactical)</th><th>Next independent test</th></tr></thead><tbody><tr><td>OHCHR August casualty total; published Sept 17, 2026. ${cite('UN-AUG')}</td><td>High for documented minimum; subsequent revisions possible</td><td>Prioritize civilian services and reporting transparency</td><td>Compare same-version OHCHR monthly series</td></tr><tr><td>OHCHR Oct 8 statement on strikes and outages. ${cite('UN-OCT')}</td><td>High for UN statement; some deaths initially attributed to local officials</td><td>Strengthen impartial assessment and winter preparedness</td><td>Follow verified OHCHR incident record</td></tr><tr><td>UN General Assembly peace statements Sept 2026. ${cite('UN-SEP')}</td><td>High for stated positions; not proof of negotiated consent</td><td>Separate diplomacy from military mandates</td><td>Confirm parties’ signed terms and observer acceptance</td></tr><tr><td>DoD civilian harm policy, 2023. ${cite('DOD-CHMR-I')}</td><td>High for historical policy text; implementation status may change</td><td>Use legal and CHMR review checkpoints</td><td>Verify policy updates and effective revisions</td></tr><tr><td>Proposed reciprocal ceasefire monitoring</td><td>Proposal, not operating mechanism</td><td>Draft only with explicit consent and independent review</td><td>Document who would authorize observers</td></tr></tbody></table></div></section>
<section class="section"><h2>Eight causal bottlenecks (analytical hypotheses)</h2><div class="columns">${['Territorial claims and sovereignty','Reciprocal security guarantees','Uncertain future battlefield leverage','Credible compliance commitments','Inspection and adjudication access','Sequencing of sanctions and relief','Domestic political acceptability','Humanitarian access and reconstruction'].map((x,i)=>card(x,`<p>Mechanism: disagreement or inadequate assurance can obstruct binding commitments. <b>Next observable:</b> formal terms, documented consent, public compliance or independent assessment.</p><p class="tiny muted">Analytical obstacle ${i+1}; not a claim of secret motives.</p>`)).join('')}</div></section>`;}
function doctrine(){return hero('Legal authority, mission scope and safeguards','An unofficial educational crosswalk of legitimate defense support, civilian protection, diplomacy and federal law enforcement.','JURISDICTION',['LEGAL REVIEW REQUIRED'])+`
<section class="section"><h2>Mandate boundary matrix</h2><div class="table-wrap"><table><thead><tr><th>Actor</th><th>Potential lawful role</th><th>Out of scope for this prototype</th></tr></thead><tbody><tr><td>DoD / U.S. military</td><td>Defense policy, lawful assistance, training and civilian-harm processes within authority.</td><td>Self-appointed foreign operations, classified tools or domestic criminal enforcement.</td></tr><tr><td>Department of State</td><td>Diplomatic negotiations, treaty considerations and end-use monitoring.</td><td>Automatic execution of proposals in this site.</td></tr><tr><td>BIS / DOJ / FBI / HSI / Treasury</td><td>Export restrictions, investigations, sanctions and prosecution under their legal jurisdictions.</td><td>Unverified public accusations or automatic punishment.</td></tr><tr><td>UN / OSCE when authorized</td><td>Diplomacy, impartial reporting and consent-based monitoring, depending on mandate.</td><td>Assumed sovereign enforcement power.</td></tr><tr><td>ICRC and impartial relief actors</td><td>Protection, impartial relief and family links under independent humanitarian mandates.</td><td>Co-option for intelligence or military leverage.</td></tr></tbody></table></div></section>
<section class="section"><h2>Law and policy checkpoints</h2><div class="columns">${card('UN Charter',`<p>Distinguish invasion and self-defense. Do not treat a de facto control line as surrender of legal sovereignty.</p>${cite('UN-CHARTER')}`)}${card('Law of armed conflict',`<p>Distinction, proportionality, precautions, humane treatment and civilian-object protections are key considerations. A public tool cannot provide case-specific legal rulings.</p>${cite('ICRC-IHL')} · ${cite('DOD-LAW')}`)}${card('Civilian Harm Mitigation and Response',`<p>DoDI 3000.17 and the CHMR Action Plan define DoD policies and support functions addressing civilian harm in its operations.</p>${cite('DOD-CHMR-I')}`)}${card('Export & end-use compliance',`<p>Commerce regulations and the State Department’s Blue Lantern monitoring have different scopes. Neither turns every component maker into an illicit supplier.</p>${cite('BIS-CHPL')} · ${cite('STATE-EUM')}`)}</div></section>
<section class="section"><details><summary>What must an authorized implementation obtain?</summary><p>Agency counsel review, statutory and regulatory authority, human rights review, host-state consent where required, formal interagency agreements, information controls, privacy impact assessment, independent oversight and correction procedures.</p></details><details><summary>What is prohibited here?</summary><p>No targeting, covert influence, espionage tooling, offensive cyber, nonconsensual data acquisition, interception, sabotage or automation of coercive decisions.</p></details></section>`;}
function casebook(){return hero('Public evidence casebook','Official policy records, UN findings and carefully scoped legal examples: each item has a different evidentiary status.','EVIDENCE DESK',['DATED SOURCES'])+`
<section class="section"><h2>Records with source posture</h2><div class="columns">${CASES.map(x=>card(x.name,`<p><span class="pill">${esc(x.classification)}</span> <span class="tiny muted">${esc(x.date)}</span></p><p><b>Evidence:</b> ${esc(x.fact)}</p><p><b>Disposition / reported total:</b> ${esc(x.disposition)}</p><p class="small muted"><b>Limit:</b> ${esc(x.limits)}</p>${cite(x.source)}`)).join('')}</div></section><section class="section"><h2>When a source conflicts with another</h2><div class="callout warn">Preserve both publication and event dates, methodology, and original language. Do not silently merge initially reported casualties with later verified UN minimums. Do not elevate an assertion into a legal determination.</div></section>`;}
function recordForm(r){const x=r||{};const val=(k)=>esc(x[k]||'');const opts=(v,arr)=>arr.map(([k,label])=>`<option value="${k}" ${x[v]===k?'selected':''}>${esc(label)}</option>`).join('');return `<form id="record-form" class="card evidence-form"><h2>${r?'Edit':'Add'} public research note</h2><p class="small muted">No classified or controlled operational information, unit locations, targeting details, personal dossiers, medical records, passwords or private identities. One public reference per record; verification belongs to human reviewers.</p><div class="form-grid"><div class="field"><label for="rec-title">Finding title *</label><input maxlength="120" id="rec-title" required value="${val('title')}" placeholder="Public finding and date"></div><div class="field"><label for="rec-date">Source date</label><input type="date" id="rec-date" value="${val('date')}"></div><div class="field"><label for="rec-type">Category</label><select id="rec-type">${opts('category',[['component','Component provenance'],['exports','Supply chain / compliance'],['financial','Public finance'],['cyber','Defensive cyber'],['humanitarian','Civilian protection'],['diplomacy','De-escalation']])}</select></div><div class="field"><label for="rec-confidence">Source status</label><select id="rec-confidence">${opts('status',[['unverified','Unverified lead'],['reported','Publicly reported'],['official','Official finding'],['judicial','Adjudicated finding'],['hypothesis','Analytical inference']])}</select></div><div class="field full"><label for="rec-url">Primary source URL (HTTPS) *</label><input id="rec-url" required type="url" maxlength="700" value="${val('sourceUrl')}" placeholder="https://www.justice.gov/..." autocomplete="off"></div><div class="field full"><label for="rec-finding">Precisely sourced finding *</label><textarea id="rec-finding" maxlength="1800" required placeholder="State what the source establishes; avoid assuming intent.">${val('finding')}</textarea></div><div class="field full"><label for="rec-limits">Uncertainties or exculpatory alternatives</label><textarea id="rec-limits" maxlength="1000" placeholder="What does this not establish?">${val('limits')}</textarea></div><div class="field full"><label for="rec-next">Next lawful verification test</label><textarea id="rec-next" maxlength="1000" placeholder="Non-invasive verification step">${val('nextTest')}</textarea></div></div><p id="form-error" class="form-error" aria-live="polite"></p><div class="btn-row"><button type="submit" class="btn primary">${r?'Save revisions':'Save local note'}</button>${r?'<button type="button" class="btn" data-action="cancel-edit">Cancel editing</button>':''}</div></form>`;}
function register(){const all=st.records.filter(r=>st.filter==='all'||r.category===st.filter);return hero('Public-source research ledger','Record public facts, alternatives, confidence and next tests. This is neither a military intelligence system nor an incident reporting portal.','LOCAL RECORDS',['NO AUTOMATIC SUBMISSION'])+`
<section class="section"><div class="columns"><div>${recordForm(st.records.find(r=>r.id===st.editing))}</div><div><div class="card"><h2>Search and review</h2><div class="field"><label for="record-filter">Category filter</label><select id="record-filter"><option value="all">All categories</option>${[['component','Component provenance'],['exports','Supply chain / compliance'],['financial','Public finance'],['cyber','Defensive cyber'],['humanitarian','Civilian protection'],['diplomacy','De-escalation']].map(([k,v])=>`<option value="${k}" ${st.filter===k?'selected':''}>${v}</option>`).join('')}</select></div><p class="small muted">Search the current page with the header search field; edit and export records locally.</p><p><b>Saved records:</b> ${st.records.length}/200</p><div class="btn-row"><button type="button" class="btn" data-action="export">Download backup</button><a class="btn secondary" href="${path('nodes')}">Prepare handoff</a></div></div><div class="card" style="margin-top:16px"><h3>Record quality</h3><ul class="bulletlist"><li>Assert the source's actual legal status, not a stronger one.</li><li>Record the rule in force when an alleged transaction occurred.</li><li>Separate corporate product origin from exporter knowledge.</li><li>Preserve alternative lawful or innocent explanations.</li><li>Avoid personal information about private individuals.</li></ul></div></div></div></section>
<section class="section"><h2>My device-local records</h2><div id="record-list">${all.length?all.map(x=>`<article class="listitem searchable"><div class="coverline"><span class="pill">${esc(x.category)}</span><span class="tiny muted">${esc(x.date||'date not specified')} · ${esc(x.status)}</span></div><h3>${esc(x.title)}</h3><p>${esc(x.finding)}</p><details><summary>Evidence qualifications & verification</summary><p><b>Limitations:</b> ${esc(x.limits||'Not entered')}</p><p><b>Next test:</b> ${esc(x.nextTest||'Not entered')}</p>${x.sha256?`<p class="mono small"><b>Locally calculated SHA-256:</b> ${esc(x.sha256)}</p>`:''}<p>${link(x.sourceUrl,'Original public source')}</p></details><div class="actions"><button class="btn small" data-action="edit" data-id="${esc(x.id)}">Edit</button><button class="btn small" data-action="handoff-from-record" data-id="${esc(x.id)}">Draft handoff</button><button class="btn small alert" data-action="delete" data-id="${esc(x.id)}">Delete</button></div></article>`).join(''):'<div class="empty">No records in this category. Add a note above or import a validated backup.</div>'}</div></section>`;}
function evidence(){return hero('Evidence & provenance lab','Five gates separate manufacturer, exporter, importer, recipient and legally supported knowledge. Hashes establish byte identity, not who authored a file.','PROVENANCE',['NO FORENSIC CERTIFICATION'])+`
<section class="section"><h2>Five evidence gates</h2><div class="columns">${[
 ['A — Physical identification','Photograph/markings of a recovered component; model or serial identifiers and independently documented recovery context.','Do not equate a model match with identification of a serialized object.'],
 ['B — Manufacturing provenance','Confirm branded part specification, production batch, and (only if evidenced) actual fabricator.','A branded manufacturer may not have fabricated each wafer or assembled each module.'],
 ['C — Export chain','Correlate shipment declarations, invoices and legal exporter–importer identity.','Distinguish exporter of record, intermediary, freight forwarder and final consignee.'],
 ['D — Actual end use','Corroborate shipment identity with proven military recipient or recovered part.','A commercially traded model can appear in weapons without proving that shipment was used.'],
 ['E — Knowing unlawful facilitation','Identify operative export restriction, legal jurisdiction, participant, mental state and supporting adjudicated or authenticated evidence.','Sanction designation, business nationality or brand appearance does not by itself prove criminal guilt.']
 ].map((z,i)=>card(z[0],`<p>${z[1]}</p><p class="small muted"><b>Stop condition:</b> ${z[2]}</p>`,'GATE '+(i+1))).join('')}</div></section>
<section class="section"><div class="columns"><div class="card"><h2>Local file SHA-256 calculator</h2><p>Choose a file you lawfully possess. Its bytes are hashed in the browser; the file is <b>not uploaded, stored or attached</b>. Maximum 25 MiB.</p><input id="hash-file" type="file" class="sr-only" aria-label="Choose file to hash"><div class="btn-row"><button type="button" class="btn primary" data-action="hash-select">Choose local file</button><button type="button" class="btn" id="hash-copy" disabled data-action="hash-copy">Copy fingerprint</button></div><div id="hash-out" class="mono small" aria-live="polite">No file selected. SHA-256 requires a supported secure browser context.</div></div><div class="card"><h2>Attach digest metadata</h2><p>Only the SHA-256 digest (not the file) can be copied into an existing local research note.</p><div class="field"><label for="hash-record">Record</label><select id="hash-record"><option value="">Select a saved record</option>${st.records.map(r=>`<option value="${esc(r.id)}">${esc(r.title)}</option>`).join('')}</select></div><button class="btn secondary" data-action="hash-attach">Attach calculated digest</button><p class="small muted">An unsigned local note and file hash are not a legally authenticated evidence chain.</p></div></div></section>
<section class="section"><h2>Preservation rules</h2><details><summary>What does SHA-256 prove?</summary><p>Files having an identical correct digest almost certainly have identical bytes. It does not prove when a file was created, where it came from, whether its contents are true, or that no one changed it before the initial hash.</p></details><details><summary>What would a legal investigation require?</summary><p>Authorized acquisition, consistent evidence handling, originals, independent verification, authenticated logs, chain-of-custody attestations and proper disclosure obligations. None are supplied by this OS.</p></details></section>`;}
function compliance(){return hero('Acquisition, sustainment and end-use assurance','Reduce unlawful diversion and downstream civilian harm while maintaining lawful Ukrainian defense support.','DEFENSE SUSTAINMENT',['NO PROCUREMENT ACTIONS'])+`
<section class="section"><h2>Procurement integrity gates</h2><div class="diagram"><div><b>Authority</b>Who approves?</div><div><b>Use</b>Lawful purpose</div><div><b>Controls</b>License & end user</div><div><b>Receipt</b>Auditable delivery</div><div><b>Review</b>Remedy & civilian impact</div></div><div class="columns">${card('Delivery does not prove end use',`<p>Track commitment, contracting, shipment and receipt separately. Avoid presenting orders as completed deliveries. Apply a review procedure proportionate to the goods and consent.</p>${cite('STATE-EUM')}`)}${card('Protect lawful defensive assistance','<p>Air defense, civilian infrastructure resilience and emergency logistics should not automatically be classified as prolongation of aggression. Verify actual use and policy objectives.</p>')}${card('Controlled items and restricted recipients',`<p>Commerce’s high-priority list identifies vulnerable dual-use categories; original brand presence alone does not establish wrongful facilitation.</p>${cite('BIS-CHPL')}`)}${card('Fraud, diversion and human rights','<p>Require legal authority and due process before escalating flagged transactions. Build corrective paths for false positives, procurement delays and essential civilian imports.</p>')}</div></section>
<section class="section"><h2>Review flow for institutions</h2><details><summary>Before disbursement</summary><p>Confirm funding source, nonprohibited end use, supplier ownership, applicable restrictions and a non-sensitive risk assessment. Consult defense and acquisition counsel.</p></details><details><summary>After transfer</summary><p>Document non-sensitive program-level outcomes, reconcile receipts with contract milestones and independently verify loss/diversion allegations where lawful.</p></details><details><summary>Escalation rule</summary><p>Do not publish suspected persons’ identities or private documents. Refer through competent, authorized offices. This app has no enforcement function.</p></details></section>`;}
function framework(){const done=CHECKS.filter(x=>st.checks[x.id]).length;return hero('Phased peace-support intervention register','Concrete public-policy proposals ordered by approximate coordination burden; dates are planning horizons, not promises.','PROGRAM DELIVERY',['PROPOSALS ONLY'])+`
<section class="section"><h2>Actions from near-term public hygiene to long-term recovery</h2><p class="section-intro">Each entry names a prospective owner, ask, mechanism, prerequisites, observable metric and stop rule. Costs are indicative only. Initiation requires competent authority and, where relevant, party consent.</p><div class="prioritypath">${ACTIONS.map(a=>`<article class="card searchable" style="margin:12px 0"><p class="kicker">${esc(a.time)}</p><h3>${esc(a.ask)}</h3><p><b>Prospective owner:</b> ${esc(a.owner)}</p><p><b>Mechanism:</b> ${esc(a.mechanism)}</p><p><b>Dependency / legal review:</b> ${esc(a.gate)}</p><p><b>Cost range:</b> ${esc(a.cost)}</p><p><b>Independent indicator:</b> ${esc(a.measure)}</p><p class="small muted"><b>Stop / fallback:</b> ${esc(a.stop)}</p></article>`).join('')}</div></section>
<section class="section"><h2>Accountability review gates</h2><div class="card"><div class="coverline"><b>${done}/${CHECKS.length} self-reviewed</b><span>${Math.round(done/CHECKS.length*100)}%</span></div><div class="progress"><div style="width:${done/CHECKS.length*100}%"></div></div>${CHECKS.map(c=>`<label class="checkitem"><input type="checkbox" data-check="${esc(c.id)}" ${st.checks[c.id]?'checked':''}><span><strong>${esc(c.title)}</strong><span class="small muted" style="display:block">${esc(c.description)}</span></span></label>`).join('')}<p class="tiny muted">Checklist is a local reading aid—not certification, readiness clearance or authorization.</p></div></section>`;}
function cyber(){return hero('Defensive cyber and information integrity','Resilience safeguards for authorized personnel, infrastructure operators and the public. No intrusion or military command functions.','CYBER SAFETY',['DEFENSIVE ONLY'])+`
<section class="section"><div class="columns">${card('Protect accounts and data','<p>Phishing-resistant MFA where supported, least privilege, offline backups, password-manager hygiene and patching. Avoid copying sensitive military or humanitarian data to personal devices.</p>')}${card('Validate information','<p>Store source URL, date, classification and independent confirmation status. Maintain a correction history. Do not turn unverifiable claims into alerts.</p>')}${card('Incident handling',`<p>Preserve authorized logs according to local law and established retention policy; isolate compromised accounts through legitimate administrators; use official reporting.</p>${cite('CISA')}`)}${card('Civilian infrastructure','<p>Advocate asset inventories, secure offline restoration plans, contingency communications and environmental/medical continuity. Never expose exploitable architecture or vulnerable sites.</p>')}</div></section><section class="section"><div class="callout warn"><b>Prohibited:</b> malware, exploitation steps, unauthorized scans, interception, offensive cyber, false-flag messaging, active unit locations, secret access and covert influence. No live monitoring is implemented.</div></section>`;}
function humanitarian(){return hero('Humanitarian, justice and reconstruction safeguards','Prioritize civilian agency and sovereignty while separating impartial relief from security investigation.','CIVILIAN PROTECTION',['INDEPENDENT MANDATES'])+`
<section class="section"><h2>Four distinct peace portfolios</h2><div class="columns">${card('I · Humanitarian confidence-building','<p>Locally supported safe access to food, health care, power, water and family-contact services, with independent verification and no automatic strategic concessions.</p><p><b>First move:</b> agree safe contact points and minimum humanitarian guarantees.</p>')}${card('II · Limited or sectoral ceasefires','<p>Reciprocal moratoria on attacks affecting agreed civilian infrastructure or humanitarian operations, with written scope and independent incident review.</p><p><b>First move:</b> mutually publish precise civilian-protection terms, without sensitive infrastructure coordinates.</p>')}${card('III · Monitored general ceasefire / armistice','<p>Independent monitoring, reporting, incident adjudication, non-reprisal mechanisms and lawful security safeguards. A ceasefire must not erase territorial sovereignty.</p><p><b>First move:</b> accepted monitoring mandate and protected observer access.</p>')}${card('IV · Regional security and reconstruction','<p>Security arrangements, fair accountability, demining, civilian-led recovery and conditional economic measures with reversal rules.</p><p><b>First move:</b> rights-centered negotiations with affected communities represented.</p>')}</div></section>
<section class="section"><h2>Civilian protection focus areas</h2><div class="columns">${card('Energy, water and health care',`<p>Monitor civilian service continuity and public health consequences without publishing sensitive system vulnerabilities.</p>${cite('UN-ENERGY')}`)}${card('POWs, missing persons and reunification','<p>Protect confidentiality, independent access and family-contact mechanisms. Do not create a public personal-name registry or use humanitarian channels as intelligence sources.</p>')}${card('Justice and due process','<p>Preserve independently documented allegations for competent courts and international mechanisms; keep presumption of innocence and victims’ privacy.</p>')}${card('Reconstruction and environmental protection','<p>Prefer transparent procurement, mine-risk education, ecosystem repair, accessible housing, local employment and affected-community oversight.</p>')}</div></section>`;}
function ceasefire(){return hero('Ceasefire verification & conditional incentives','A conceptual independent monitoring design: incidents are coarse public categories, not live coordinates or military deployments.','VERIFICATION',['REQUIRES ALL-PARTY CONSENT'])+`
<section class="section"><h2>Model incident adjudication protocol</h2><div class="diagram"><div><b>1</b>Logged allegation</div><div><b>2</b>Receipt and preservation</div><div><b>3</b>Independent cross-check</div><div><b>4</b>Neutral determination</div><div><b>5</b>Review and remedy</div></div><div class="table-wrap"><table><thead><tr><th>Rule</th><th>Proposed mechanism</th><th>Protection requirement</th></tr></thead><tbody><tr><td>Scope</td><td>Written prohibitions agreed by both sides, with separate handling for ambiguous incidents</td><td>No implicit recognition of annexation</td></tr><tr><td>Evidence</td><td>Timestamp, coarse incident class, authenticated reports and independently lawful observation</td><td>Do not publish exact vulnerable civilian or military site positions</td></tr><tr><td>Initial review</td><td>Receipt acknowledgment target of 24 hours after an accepted report</td><td>Timeline is a proposal, not currently implemented</td></tr><tr><td>Adjudication</td><td>Provisional determination target within 72 hours when evidence allows; unresolved otherwise</td><td>Independent review, rebuttal and correction paths</td></tr><tr><td>Accidents</td><td>Separate unintended incidents, contested evidence and verified intentional breaches</td><td>No automatic escalation from unverified allegation</td></tr><tr><td>Response</td><td>Proportionate, pre-agreed remedy or reassessment; never automated retaliation</td><td>Humanitarian access remains protected</td></tr></tbody></table></div></section>
<section class="section"><h2>Reciprocal conditional exchange</h2><div class="columns">${card('ACTION → VERIFIED RESPONSE','<p>Both parties publicly commit to a narrowly defined protection rule. Independent agreed monitors verify compliance for a stated observation period.</p>')}${card('VERIFIED RESPONSE → CONDITIONAL BENEFIT','<p>Only after a documented threshold is met, participants consider reversible confidence-building benefits subject to legal authority.</p>')}${card('VIOLATION → REVIEW → PROPORTIONATE REMEDY','<p>Credibly documented breaches trigger protected investigation, rebuttal rights and pre-negotiated remedies; never automatic force.</p>')}${card('FAILURE FALLBACK','<p>Return to humanitarian minimums, maintain hotlines and records, and reassess guarantees. Do not abandon civilian protections.</p>')}</div></section>
<section class="section"><details><summary>False compliance and rearmament risks</summary><p>Access constraints, camera blind spots, manipulated timestamps, electronic interference and non-state spoilers could produce incorrect findings. Use mutually agreed standards, diverse independent sources and uncertainty categories; do not claim certainty from remote sensing alone.</p></details><details><summary>What does this tool actually do?</summary><p>Displays the agreed-design questions and stores public research notes. It cannot authenticate incidents, calculate real compliance rates, connect to observers, send alerts or adjudicate violations.</p></details></section>`;}
function metrics(){return hero('Indicators, baselines and decision triggers','A public monitoring rubric that avoids invented live telemetry or probabilities.','EVALUATION',['BASELINES MUST BE DATED'])+`
<section class="section"><h2>Outcome dashboard specification</h2><div class="table-wrap"><table><thead><tr><th>Indicator</th><th>Definition and public source</th><th>How to interpret</th></tr></thead><tbody>${[
 ['Civilian killed/injured','OHCHR verified monthly data; count and reporting vintage','Verified floor, not complete live count'],
 ['Civilian electricity/water uptime','Audited restoration reports and service-operator releases','Never publish sensitive damage map'],
 ['Humanitarian access','Independent agencies’ publicly reported access events','Access count ≠ beneficiary needs fully met'],
 ['POW and missing-person progress','Aggregated confirmed releases/tracing cases with consent','No individual records'],
 ['Ceasefire reports','Independent observer verified events, disputed events separately','No zero-incident inference without observer coverage'],
 ['Industrial diversion','Public adjudicated cases and enforcement releases','More cases can reflect better enforcement, not more underlying diversion'],
 ['Negotiating milestones','Written, acknowledged proposals and implemented agreements','Statements ≠ commitments'],
 ['Non-recurrence','Public durability benchmarks at 6, 12, 24 months','Requires longitudinal review']
 ].map(a=>`<tr><td><b>${a[0]}</b></td><td>${a[1]}</td><td>${a[2]}</td></tr>`).join('')}</tbody></table></div></section>
<section class="section"><h2>Known public-source baseline</h2><div class="metrics"><div class="metric"><div class="value">372</div><div class="label">Civilians killed, Aug 2026</div><div class="meta">UN verified minimum · ${cite('UN-AUG')}</div></div><div class="metric"><div class="value">2,349</div><div class="label">Civilians injured, Aug 2026</div><div class="meta">UN verified minimum · ${cite('UN-AUG')}</div></div><div class="metric"><div class="value">0</div><div class="label">Live data feeds</div><div class="meta">Offline baseline only</div></div><div class="metric"><div class="value">Draft</div><div class="label">Ceasefire monitoring protocol</div><div class="meta">Not negotiated or active</div></div></div></section>
<section class="section"><h2>Decision tree</h2><div class="diagram"><div><b>Incident</b>Claim arrives</div><div><b>Verify</b>Is evidence enough?</div><div><b>Consent</b>Is review authorized?</div><div><b>Protect</b>Any civilian risk?</div><div><b>Respond</b>Correct / refer / hold</div></div><p class="small muted">Do not derive probabilities or progress statistics from a single snapshot; obtain baseline and denominator information first.</p></section>`;}
function premortem(){return hero('24-month catastrophic-failure premortem','Imagine the architecture failed and civilians experienced additional harm. What observable warning signs should trigger redesign?','RED TEAM',['NO PROBABILITY INVENTED'])+`
<section class="section"><h2>Failure modes and stop rules</h2><div class="columns">${[
 ['Monitoring used for targeting','Sensitive location data or identifiable civilians inadvertently published','Block location-level exports; strip protected fields; suspend sharing and notify responsible data owners'],
 ['Unverified accusations harm innocent suppliers','Brand origin confused with knowing violation; suppliers or civilians penalized','Require shipment-level proof, law, intent and fair correction before escalation'],
 ['Ceasefire exploited for renewed aggression','Lack of independent access or response process permits repeated violations','Hold conditional relief, preserve defensive safeguards and reopen neutral monitoring terms'],
 ['False compliance claims','Manipulated data or uneven observer access appears as zero violations','Publish coverage and uncertainty; do not infer compliance from missing reports'],
 ['Humanitarian independence compromised','Relief data used to identify persons or support intelligence collection','Separate records and institutional mandates; terminate improper handoff'],
 ['Reconstruction captures resources','Conflicts of interest, cost inflation or exclusion of displaced populations','Transparent tenders, community panels, audits and public remedies'],
 ['Cyber compromise or data leakage','Local device infected, backups shared publicly or keys copied','Use no sensitive data; offline backups, rapid containment and controlled revocation'],
 ['Diplomatic initiative lacks sovereign consent','External actors impose terms unsupported by Ukraine or the parties','Stop implementation; preserve legal claims and locally controlled humanitarian support']
 ].map((r,i)=>card(r[0],`<p><b>Warning signal:</b> ${r[1]}</p><p class="small"><b>Mitigation/stop:</b> ${r[2]}</p>`,'FAILURE TEST '+(i+1))).join('')}</div></section>
<section class="section"><h2>Strongest dissenting analyses</h2><details><summary>A rapid freeze could reduce immediate civilian losses even before a full security settlement</summary><p>A monitored limited ceasefire may save lives faster than a comprehensive accord. This approach faces enforcement and rearmament concerns; evaluate with independent compliance and subsequent recurrence data.</p></details><details><summary>An insecure ceasefire could preserve conditions for renewed violence</summary><p>A cessation without guarantees, accountability and Ukrainian consent may defer rather than resolve coercion. This does not mean diplomatic talks should be delayed indefinitely.</p></details><details><summary>Pressure and sanctions can cause civilian or substitution harms</summary><p>Enforcement may constrain restricted procurement but also incentivize illicit routes and burdens on civilians. Assess exemptions, substitution and human-rights outcomes before claiming effect.</p></details></section>`;}
function handoffObj(node,rec){return {schema:'pra.reciprocal_public_handoff',version:1,sender_node:'us_military_concept',recipient_node:node+'_proposed',created_at:new Date().toISOString(),handling:'PUBLIC_ONLY',submitted:false,authenticity:'UNSIGNED_LOCAL_DRAFT',requested_action:'independent_review_only',lead:{id:rec?.id||'public_example_only',title:rec?.title||'Unsubmitted public-source example',category:({'component':'manufacturing_provenance','exports':'export_controls','financial':'financial_integrity','cyber':'defensive_cyber','humanitarian':'civilian_protection','diplomacy':'diplomatic_offramp'})[rec?.category]||'civilian_protection',source_url:rec?.sourceUrl||'https://ukraine.un.org/en/323265-un-general-assembly-calls-protection-civilians-and-just-peace-ukraine',evidence_level:rec?.status||'public_report',summary:rec?.finding||'Example draft only; no official agency has reviewed or received it.',limitations:rec?.limits||'Public example; no official submission'},limitations:['Non-sensitive public-source note only','Not an official report, intelligence record or case submission','Independent review and lawful institutional consent required'],consent_scope:'manual_user_selected_export'};}
function nodes(){return hero('Reciprocal institutional node contracts','Future agencies may share PUBLIC evidence summaries only through separately authorized interfaces. None are connected.','INTEROPERABILITY',['UNSIGNED LOCAL JSON'])+`
<section class="section"><h2>Mission-separated coordination map</h2><div class="nodegrid">${NODES.map(n=>card(n.name,`<p><span class="pill">${esc(n.status)}</span></p><p class="small">${esc(n.scope)}</p>`,n.id.toUpperCase())).join('')}</div></section>
<section class="section"><div class="columns"><div class="card"><h2>Manual, unsubmitted public-only handoff</h2><div class="field"><label for="node-target">Proposed receiving node</label><select id="node-target">${NODES.filter(n=>n.id!=='dod'&&n.id!=='icrc').map(n=>`<option value="${n.id}">${esc(n.name)}</option>`).join('')}</select></div><div class="field"><label for="node-record">Optional local research note</label><select id="node-record"><option value="">Public sample only</option>${st.records.map(r=>`<option value="${esc(r.id)}">${esc(r.title)}</option>`).join('')}</select></div><div class="btn-row"><button class="btn primary" data-action="handoff">Download unsigned draft</button><button class="btn" data-action="schema">Download example contract</button></div><p class="small muted">No emails, notifications, API messages, official access or receiving acknowledgments are generated. Do not include classified or controlled operational data.</p></div><div class="card"><h2>Previous editions</h2><p>Import a user-selected compatible public-only handoff from Secret Service or FBI concept editions, or export this node’s public research notes. Data is reviewed locally before application.</p><div class="btn-row"><button class="btn secondary" data-action="import">Validate JSON import</button><button class="btn" data-action="export">Back up current notes</button></div><p class="small muted">A public-only handoff schema is an interchange idea, not a secure data exchange, authority delegation or authentic provenance signature.</p></div></div></section>
<section class="section"><h2>Future authorization gate</h2><details><summary>Prerequisites for any real institutional integration</summary><p>Formal mandate and data-sharing agreement; named account owners; classification guardrails; mutual identity proof; cryptographic signatures; authenticated transport; privacy assessment; human-rights and humanitarian protections; field-level release approval; immutable independent logs; correction and revocation process.</p></details></section>`;}
function governance(){return hero('Privacy, governance, backup and evidence sources','Durable local files with clear limitations; zero automatic data transfer or state action.','DATA SOVEREIGNTY',['PUBLIC NOTES ONLY'])+`
<section class="section"><div class="columns"><div class="card"><h2>Portable records</h2><div class="btn-row"><button class="btn primary" data-action="export">Export device-local JSON</button><button class="btn" data-action="import">Review import</button><button class="btn alert" data-action="reset">Delete device-local data</button></div><p>Storage mode: <span id="storage-inline">${esc(st.storage)}</span></p><p class="small muted">IndexedDB is not encrypted here. On blocked storage, notes exist only in memory and can disappear when the tab closes. Backups require deliberate downloads and remain the user's responsibility.</p></div><div class="card"><h2>Preferences</h2><label class="checkitem"><input type="checkbox" id="hud-toggle" ${st.hud?'checked':''}><span><strong>Show optional evidence-review progress HUD</strong><span class="small muted" style="display:block">Checklist reading progress only; no gamification that rewards aggressive acts.</span></span></label>${st.hud?readiness():''}<p class="small muted">Language: English. Additional translations not yet verified. Light/dark and reduced-motion support included.</p></div></div></section>
<section class="section"><h2>Local, editable event history</h2><div class="card audit"><ol>${st.events.length?st.events.slice().reverse().slice(0,35).map(e=>`<li class="small">${esc(e.time)} · ${esc(e.action)} · ${esc(e.detail||'')}</li>`).join(''):'<li>No local actions logged.</li>'}</ol><p class="tiny muted">Not tamper-evident, not forensic and not transferable as a certified government record.</p></div></section>
<section class="section"><h2>Zero-Harm / Anti-Inversion guardrails</h2><div class="columns">${card('Never enable','<ul class="bulletlist"><li>No operational military targeting, unit tracking, damage optimization or strike planning.</li><li>No offensive cyber, unlawful collection, surveillance, propaganda or impersonation.</li><li>No sanctions evasion or weapons procurement.</li><li>No personal or protected information collection.</li></ul>')}${card('Always require','<ul class="bulletlist"><li>Sovereignty, IHL, humanitarian independence and lawful authority.</li><li>Source reliability, uncertainty, corrections and exculpatory possibilities.</li><li>Independent consent and proportional responses.</li><li>Measures of actual civilian safety and peace durability.</li></ul>')}</div></section>
<section class="section"><h2>Official research source registry</h2>${sourcesHTML()}</section><section class="section"><h2>Attributions & licenses</h2><div class="callout">Independent editorial and software implementation: Foster + Navi / Planetary Restoration Archive. Original software is MIT-licensed. Source material remains with its respective publishers; citation is not institutional endorsement. Structural continuity with prior FBI and USSS and FBI public concept editions is conceptual only.</div></section>`;}
const VIEWS={home,sitrep,doctrine,casebook,register,evidence,compliance,framework,cyber,humanitarian,ceasefire,metrics,premortem,nodes,governance};
function shell(){const r=ROUTES.find(x=>x.id===PAGE)||ROUTES[0],groups=[...new Set(ROUTES.map(x=>x.group))];$('#app-shell').innerHTML=`<header class="topbar"><button class="headbutton hamburger" data-action="drawer" aria-label="Open navigation" aria-controls="sidebar" aria-expanded="false">☰</button><a class="brand" href="${path('home')}"><span class="mark" aria-hidden="true">◈</span><span class="brand-title">U.S. Military Peace OS<small class="brand-sub">Edition 03 · independent, non-governmental</small></span></a><span class="headnote">Foster + Navi / Planetary Restoration Archive</span><nav class="top-actions" aria-label="Global controls"><input id="site-search" type="search" aria-label="Search this page" placeholder="Search page..."><span class="connect" id="net-indicator">Network check</span><button class="headbutton smallhide" data-action="theme" type="button" aria-label="Toggle light or dark theme">◑ Theme</button><button class="headbutton smallhide" data-action="print" type="button">Print</button></nav></header><div id="drawer-overlay" class="drawer-overlay"></div><div class="layout"><aside id="sidebar" class="sidebar" aria-label="Module navigation"><div class="statusline"><b class="small">Navigation tree</b><button class="btn small drawer-close" style="display:none" data-action="close-drawer" aria-label="Close navigation">Close ×</button></div>${groups.map(g=>`<div class="group-title">${esc(g)}</div>${ROUTES.filter(x=>x.group===g).map(x=>`<a class="nav-item" href="${path(x.id)}" ${x.id===PAGE?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${x.sym}</span><span>${esc(x.title)}<small>${esc(x.hint)}</small></span></a>`).join('')}`).join('')}<div class="sidefoot"><b>No authorized institutional connection.</b><p>This is a public-source, local-first prototype.</p><span id="storage-sidebar">Local storage: checking...</span></div></aside><div class="workspace"><div class="breadcrumbs"><a href="${path('home')}">Overview</a> / ${esc(r.title)} / <span>${DATE}</span></div><main id="main" tabindex="-1"></main><p id="search-status" aria-live="polite"></p><footer class="footer"><p><b>Unofficial prototype.</b> Not the U.S. military, not a government data system, not a command platform. ${cite('DOD-CHMR')}.</p><div class="footerlinks"><a href="${path('governance')}">Privacy & sources</a><a href="${path('nodes')}">Public-only handoffs</a><a href="${path('humanitarian')}">Civilian protection</a></div></footer></div></div><div id="toast" class="toast hidden" role="status" aria-live="polite"></div><input type="file" id="import-file" accept="application/json,.json" class="sr-only" aria-label="Select a JSON file for import"><dialog id="import-dialog" aria-labelledby="import-heading"><h2 id="import-heading">Import preview</h2><p id="import-preview"></p><div class="field"><label for="conflict-policy">Existing record ID collision</label><select id="conflict-policy"><option value="keep">Keep existing</option><option value="replace">Replace existing with imported record</option><option value="copy">Keep both, assign new ID to imported</option></select></div><div class="btn-row"><button class="btn primary" data-action="apply-import">Apply reviewed import</button><button class="btn" data-action="cancel-import">Cancel</button></div></dialog>`;}
function render(){let main=$('#main');if(!main)return;const view=VIEWS[PAGE]||home;main.innerHTML=view();updateStatus();searchPage();}
function updateStatus(){const n=$('#net-indicator');if(n)n.textContent=navigator.onLine?'Browser online':'Browser offline';const ss=$('#storage-sidebar');if(ss)ss.textContent='Local storage: '+(st.storage==='indexeddb'?'IndexedDB':st.storage==='memory'?'memory-only':st.storage);const d=$('#storage-inline');if(d)d.textContent=st.storage;const w=$('#storage-warning');if(w)w.textContent=st.storage==='indexeddb'?'IndexedDB active on this device.':'Memory-only mode: export before closing or data will be lost.';}
function searchPage(){const q=st.search.toLowerCase().trim();let all=0,show=0;$$('#main .searchable').forEach(e=>{all++;const yes=!q||e.textContent.toLowerCase().includes(q);e.classList.toggle('hidden',!yes);if(yes)show++;});$('#search-status').textContent=q?`Showing ${show} of ${all} searchable sections on this page.`:'';}
function openDrawer(){const s=$('#sidebar');s.classList.add('open');$('#drawer-overlay').classList.add('active');$('[data-action="drawer"]').setAttribute('aria-expanded','true');$('.drawer-close')?.focus();}
function closeDrawer(){const s=$('#sidebar');s.classList.remove('open');$('#drawer-overlay').classList.remove('active');$('[data-action="drawer"]').setAttribute('aria-expanded','false');$('[data-action="drawer"]')?.focus();}
/* IndexedDB routines. Private and file contexts may refuse persistence; memory fallback is explicit. */
function openDB(){return new Promise((res,rej)=>{if(!('indexedDB' in window))return rej(Error('IndexedDB unavailable'));const req=indexedDB.open(DB,VERSION);req.onupgradeneeded=()=>{const d=req.result;if(!d.objectStoreNames.contains('records'))d.createObjectStore('records',{keyPath:'id'});if(!d.objectStoreNames.contains('events'))d.createObjectStore('events',{keyPath:'id'});};req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error||Error('DB error'));});}
function operation(store,mode,cb){return new Promise((res,rej)=>{if(!st.db)return rej(Error('memory-only'));let tx=st.db.transaction(store,mode),s=tx.objectStore(store),value;try{value=cb(s);}catch(e){rej(e);return;}let result; if(value && typeof value==='object'&&'onsuccess' in value){value.onsuccess=()=>result=value.result;value.onerror=()=>rej(value.error);}tx.oncomplete=()=>res(result);tx.onerror=()=>rej(tx.error||Error('DB transaction failure'));tx.onabort=()=>rej(tx.error||Error('DB transaction aborted'));});}
const clean=(v,max)=>String(v??'').slice(0,max);
function normalize(raw){if(!raw||typeof raw!=='object'||Array.isArray(raw))return null;const categ=['component','exports','financial','cyber','humanitarian','diplomacy'];const statuses=['unverified','reported','official','judicial','hypothesis'];const src=clean(raw.sourceUrl??raw.source_url,700);const x={id:clean(raw.id,90),title:clean(raw.title,120),date:clean(raw.date??raw.recordDate,10),category:categ.includes(raw.category)?raw.category:'exports',status:statuses.includes(raw.status)?raw.status:'unverified',sourceUrl:src,finding:clean(raw.finding??raw.summary,1800),limits:clean(raw.limits??raw.gap,1000),nextTest:clean(raw.nextTest??raw.nextStep,1000),sha256:/^[a-f0-9]{64}$/i.test(raw.sha256||'')?raw.sha256.toLowerCase():'',createdAt:clean(raw.createdAt,40),updatedAt:clean(raw.updatedAt,40)};if(!x.id||x.title.length<4||!url(x.sourceUrl)||!x.finding||x.finding.length>1800)return null;return x;}
async function initStore(){try{st.db=await openDB();const [rs,ev]=await Promise.all([operation('records','readonly',s=>s.getAll()),operation('events','readonly',s=>s.getAll())]);st.records=(rs||[]).map(normalize).filter(Boolean);st.events=(ev||[]).filter(x=>x&&x.action);st.storage='indexeddb';}catch(e){st.storage='memory';console.warn('Persistent storage unavailable:',e);}try{st.checks=JSON.parse(localGet('checks','{}'));if(!st.checks||typeof st.checks!=='object')st.checks={};}catch{st.checks={};}st.theme=localGet('theme','light')==='dark'?'dark':'light';st.hud=localGet('hud','false')==='true';document.documentElement.dataset.theme=st.theme;render();}
async function addEvent(action,detail=''){const ev={id:newId(),time:new Date().toISOString(),action:clean(action,100),detail:clean(detail,130)};st.events.push(ev);if(st.events.length>120)st.events=st.events.slice(-120);if(st.db){try{await operation('events','readwrite',s=>s.put(ev));}catch{st.storage='memory';toast('Persistent event logging failed; current session is memory-only.');}}}
async function persist(r){const idx=st.records.findIndex(x=>x.id===r.id);if(idx>=0)st.records[idx]=r;else st.records.push(r);if(st.db){try{await operation('records','readwrite',s=>s.put(r));}catch{st.storage='memory';toast('Persistent storage write failed; export a backup now.');}}}
async function drop(id){st.records=st.records.filter(x=>x.id!==id);if(st.db){try{await operation('records','readwrite',s=>s.delete(id));}catch{st.storage='memory';toast('DB deletion did not persist.');}}}
function download(name,value){const b=new Blob([value],{type:'application/json;charset=utf-8'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;a.hidden=true;document.body.append(a);a.click();setTimeout(()=>{a.remove();URL.revokeObjectURL(u);},900);}
async function exportAll(){const data={app:APP,schemaVersion:1,createdAt:new Date().toISOString(),handling:'PUBLIC_ONLY',records:st.records,checks:st.checks,note:'Unofficial local research backup; not an evidentiary or government record.'};download('us_military_peace_backup_'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(data,null,2));await addEvent('manual backup exported',String(st.records.length));toast('Local JSON backup downloaded; not transmitted.');}
function fromImported(data){if(!data||typeof data!=='object'||Array.isArray(data))throw Error('Expected a JSON object.');let items=[];if(data.app===APP&&data.schemaVersion===1&&Array.isArray(data.records))items=data.records;else if(data.app==='fbi_integrity_research_os'&&data.schemaVersion===1&&Array.isArray(data.records))items=data.records;else if(data.app==='pra_financial_integrity_os'&&[1,2].includes(data.schemaVersion)&&Array.isArray(data.leads)){items=data.leads.map(x=>({...x,category:({'manufacturing_provenance':'component','supply_chain':'exports','export_controls':'exports','financial_integrity':'financial','diplomatic_offramp':'diplomacy','civilian_protection':'humanitarian','defensive_cyber':'cyber'})[x.category]||'exports',status:({'judicial_finding':'judicial','reported_allegation':'reported','hypothesis':'hypothesis'})[x.claimType]||'unverified',sourceUrl:x.sourceUrl??x.source_url,finding:x.summary,limits:x.gap,nextTest:x.nextStep}));}else if(data.schema==='pra.reciprocal_public_handoff'&&data.version===1&&data.handling==='PUBLIC_ONLY'){const a=data.lead;if(!a||!a.source_url||!a.title)throw Error('No supported public source record in this handoff.');items=[{id:'handoff-'+clean(a.id||newId(),60),title:a.title,sourceUrl:a.source_url,finding:a.summary||'Imported public-only handoff; recipient has not validated this statement.',limits:a.limitations||'Unsigned unsubmitted prototype exchange; verify independently.',category:({'export_controls':'exports','manufacturing_provenance':'component','supply_chain':'exports','financial_integrity':'financial','diplomatic_offramp':'diplomacy','civilian_protection':'humanitarian','defensive_cyber':'cyber'})[a.category]||'exports',status:'unverified',nextTest:'Verify source independently; no official receipt.'}];}else throw Error('Unrecognized JSON format. Only military/FBI local backups, prior FBI/USSS backups or public-only handoff v1 accepted.');if(items.length>200)throw Error('Backup exceeds 200 records.');const arr=items.map(x=>normalize(x));if(arr.some(x=>!x))throw Error('One or more records failed validation. Source URLs must use HTTPS, with required title and finding.');if(new Set(arr.map(x=>x.id)).size!==arr.length)throw Error('Duplicate IDs within imported file.');return arr;}
async function chooseImport(file){if(!file)return;if(file.size>2*1024*1024){toast('Import rejected: 2 MiB file limit.');return;}try{let raw=JSON.parse(await file.text()),records=fromImported(raw);const existing=new Set(st.records.map(x=>x.id));st.pending=records;$('#import-preview').textContent=`${records.length} validated public note(s); ${records.filter(x=>existing.has(x.id)).length} existing ID collision(s). Records stay in this browser unless manually exported.`;$('#import-dialog').showModal();$('#conflict-policy').focus();}catch(e){toast('Import rejected: '+e.message);}}
async function applyImport(){if(!st.pending)return;const mode=$('#conflict-policy').value;let map=new Map(st.records.map(r=>[r.id,r])),applied=0;const changes=[];for(let r of st.pending){let x={...r};if(map.has(x.id)){if(mode==='keep')continue;if(mode==='copy')x.id=newId();}map.set(x.id,x);changes.push(x);applied++;}if(map.size>200){toast('Import exceeds 200-record cap; archive first.');return;}if(st.db){try{await operation('records','readwrite',s=>{changes.forEach(x=>s.put(x));});}catch{st.storage='memory';toast('Database write failed; export after import.');}}st.records=[...map.values()];st.pending=null;$('#import-dialog').close();await addEvent('manual import applied',String(applied));render();toast(applied+' note(s) imported locally; no agency contacted.');}
async function hashFile(f){let el=$('#hash-out');if(!f||!el)return;if(f.size>25*1024*1024){el.textContent='Rejected: file exceeds 25 MiB limit.';return;}if(!crypto?.subtle){el.textContent='Web Crypto unavailable here. Use localhost or HTTPS; no fingerprint produced.';return;}el.textContent='Calculating locally…';try{const dig=await crypto.subtle.digest('SHA-256',await f.arrayBuffer());st.hash=[...new Uint8Array(dig)].map(b=>b.toString(16).padStart(2,'0')).join('');st.hashname=f.name;el.textContent=f.name+' · '+f.size+' bytes · SHA-256: '+st.hash;$('#hash-copy').disabled=false;await addEvent('local file hashed','name: '+f.name.slice(0,60));}catch(e){el.textContent='Hash failed: '+e.message;}}
async function clickAction(btn){const act=btn.dataset.action,id=btn.dataset.id;if(act==='drawer')return openDrawer();if(act==='close-drawer')return closeDrawer();if(act==='theme'){st.theme=st.theme==='light'?'dark':'light';document.documentElement.dataset.theme=st.theme;localSet('theme',st.theme);return;}if(act==='print')return window.print();if(act==='export')return exportAll();if(act==='import')return $('#import-file')?.click();if(act==='cancel-import'){st.pending=null;$('#import-dialog').close();return;}if(act==='apply-import')return applyImport();if(act==='reset'){if(!confirm('Delete ALL local research notes, local events and checklist state? Export first. This is irreversible without a backup.'))return;st.records=[];st.events=[];st.checks={};localSet('checks','{}');if(st.db)try{await operation('records','readwrite',s=>s.clear());await operation('events','readwrite',s=>s.clear());}catch{st.storage='memory';}render();toast('Local research data cleared.');return;}if(act==='edit'){st.editing=id;render();$('#rec-title')?.focus();return;}if(act==='cancel-edit'){st.editing=null;render();return;}if(act==='delete'){const x=st.records.find(r=>r.id===id);if(x&&confirm('Delete this research note from local storage?')){await drop(id);await addEvent('note deleted',id);render();toast('Local note deleted.');}return;}if(act==='handoff-from-record'){location.href=path('nodes')+'?record='+encodeURIComponent(id);return;}if(act==='schema'){download('us_military_reciprocal_handoff_example.json',JSON.stringify(handoffObj('usss',null),null,2));return;}if(act==='handoff'){let target=$('#node-target').value,rec=st.records.find(r=>r.id===$('#node-record').value);download('us_military_unsubmitted_handoff_'+target+'.json',JSON.stringify(handoffObj(target,rec),null,2));await addEvent('public handoff drafted',target);toast('Unsubmitted JSON downloaded locally. No agency contact occurred.');return;}if(act==='hash-select')return $('#hash-file')?.click();if(act==='hash-copy'){if(!st.hash)return;try{await navigator.clipboard.writeText(st.hash);toast('Fingerprint copied.');}catch{toast('Clipboard denied; select digest text to copy.');}return;}if(act==='hash-attach'){if(!st.hash)return toast('Calculate a hash first.');const x=st.records.find(r=>r.id===$('#hash-record').value);if(!x)return toast('Select a record.');const updated={...x,sha256:st.hash,updatedAt:new Date().toISOString()};await persist(updated);await addEvent('hash attached as metadata',x.id);render();toast('Digest saved as local metadata; original file not retained.');return;}}
async function formSubmit(ev){if(ev.target.id!=='record-form')return;ev.preventDefault();let v=id=>($('#rec-'+id)?.value||'').trim();if(st.records.length>=200&&!st.editing){$('#form-error').textContent='Maximum 200 records. Archive or export first.';return;}const orig=st.records.find(x=>x.id===st.editing),now=new Date().toISOString();const rec=normalize({id:orig?.id||newId(),title:v('title'),date:v('date'),category:v('type'),status:v('confidence'),sourceUrl:v('url'),finding:v('finding'),limits:v('limits'),nextTest:v('next'),sha256:orig?.sha256,createdAt:orig?.createdAt||now,updatedAt:now});if(!rec){$('#form-error').textContent='Required: title ≥4 letters, valid HTTPS source and factual finding.';return;}await persist(rec);await addEvent(orig?'research note revised':'research note added',rec.id);st.editing=null;render();toast('Saved locally'+(st.storage==='memory'?' in memory only':'')+'.');}
async function initSW(){if(!('serviceWorker' in navigator)||location.protocol==='file:'){st.sw='unavailable from file';return;}try{const reg=await navigator.serviceWorker.register(ROOT+'service_worker.js',{scope:ROOT});st.sw='registered';if(reg.waiting)toast('Offline update ready: close and reopen tabs to use latest version.');}catch(e){st.sw='unavailable';console.info('Service worker unavailable',e);}}
function bind(){document.addEventListener('click',ev=>{let b=ev.target.closest('[data-action]');if(b)clickAction(b).catch(err=>toast('Action error: '+err.message));if(ev.target.id==='drawer-overlay')closeDrawer();});document.addEventListener('submit',ev=>formSubmit(ev).catch(err=>toast('Save error: '+err.message)));document.addEventListener('change',ev=>{const x=ev.target;if(x.dataset.check){const checkId=x.dataset.check;st.checks[checkId]=x.checked;localSet('checks',JSON.stringify(st.checks));render();$('[data-check="'+checkId+'"]')?.focus();}if(x.id==='record-filter'){st.filter=x.value;render();$('#record-filter')?.focus();}if(x.id==='import-file'){chooseImport(x.files?.[0]);x.value='';}if(x.id==='hash-file'){hashFile(x.files?.[0]);x.value='';}if(x.id==='hud-toggle'){st.hud=x.checked;localSet('hud',String(st.hud));render();$('#hud-toggle')?.focus();}});$('#site-search')?.addEventListener('input',ev=>{st.search=ev.target.value;searchPage();});document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&$('#sidebar').classList.contains('open'))closeDrawer();if(ev.key==='Tab'&&$('#sidebar').classList.contains('open')&&window.innerWidth<=850){const all=$$('#sidebar a,#sidebar button').filter(n=>!n.disabled);const f=all[0],l=all[all.length-1];if(ev.shiftKey&&document.activeElement===f){ev.preventDefault();l.focus();}else if(!ev.shiftKey&&document.activeElement===l){ev.preventDefault();f.focus();}}});window.addEventListener('online',updateStatus);window.addEventListener('offline',updateStatus);}
async function boot(){shell();bind();await initStore();if(PAGE==='nodes'){const id=new URLSearchParams(location.search).get('record'),x=$('#node-record');if(id&&st.records.some(r=>r.id===id)&&x)x.value=id;}await initSW();}
boot().catch(e=>{console.error('Startup failed',e);const main=$('#main');if(main)main.textContent='Application startup failed. Use static no-script module pages and consult README.';});
})();
